mutation CreatePost(
  $channelId: ChannelId!,
  $text: String!,
  $schedulingType: SchedulingType!,
  $shareMode: ShareMode!
) {
  createPost(input: {
    channelId: $channelId
    text: $text
    schedulingType: $schedulingType
    mode: $shareMode
  }) {
    ... on PostActionSuccess {
      post {
        id
        status
        text
        assets {
          id
          mimeType
        }
      }
    }
    ... on MutationError {
      message
    }
  }
}
